public static class Triangulation {
    public record Edge(int a, int b) : IComparable<Edge> {
        public int CompareTo(Edge e) {
            int c = a.CompareTo(e.a);
            return c != 0 ? c : b.CompareTo(e.b);
        }
    }
    public record Triangle(int a, int b, int c) : IComparable<Triangle> {
        public int CompareTo(Triangle t) {
            int result = a.CompareTo(t.a);
            if (result == 0)
                result = b.CompareTo(t.b);
            return result != 0 ? result : c.CompareTo(t.c);
        }
        public int[] Sites() {
            return new int[] { a, b, c };
        }
    }
    public static Edge Key(int a, int b) {
        return new Edge(Math.Min(a, b), Math.Max(a, b));
    }
    public static Triangle Canonical(int a, int b, int c) {
        return a < b && a < c ? new Triangle(a, b, c) : b < c ? new Triangle(b, c, a) : new Triangle(c, a, b);
    }
    public record Insertion(string kind, Triangle containing, int visible, int flips, int triangles,
                            int hull) {
    }
    public sealed class Model {
        public List<Predicates.Point> points;
        public Dictionary<Edge, int> directed = new();
        public Triangle initial;
        public Model(List<Predicates.Point> points) {
            this.points = points;
            initial = Predicates.Orient(points[1], points[2], points[3]) > 0 ? new Triangle(1, 2, 3)
                                                                             : new Triangle(1, 3, 2);
            Add(initial.a, initial.b, initial.c);
        }
        public void Add(int a, int b, int c) {
            directed[new Edge(a, b)] = c;
            directed[new Edge(b, c)] = a;
            directed[new Edge(c, a)] = b;
        }
        public void Remove(int a, int b, int c) {
            directed.Remove(new Edge(a, b));
            directed.Remove(new Edge(b, c));
            directed.Remove(new Edge(c, a));
        }
        public List<Triangle> Triangles() {
            SortedSet<Triangle> result = new();
            foreach (KeyValuePair<Edge, int> entry in directed)
                result.Add(Canonical(entry.Key.a, entry.Key.b, entry.Value));
            return new(result);
        }
        public List<Edge> HullEdges() {
            List<Edge> result = new();
            foreach (Edge e in directed.Keys)
                if (!directed.ContainsKey(new Edge(e.b, e.a)))
                    result.Add(e);
            result.Sort();
            return result;
        }
        public Insertion Insert(int site) {
            Triangle containing = null;
            foreach (Triangle t in Triangles())
                if (Predicates.Orient(points[t.a], points[t.b], points[site]) > 0 &&
                    Predicates.Orient(points[t.b], points[t.c], points[site]) > 0 &&
                    Predicates.Orient(points[t.c], points[t.a], points[site]) > 0) {
                    containing = t;
                    break;
                }
            SortedSet<Edge> check = new();
            int visible = 0;
            if (containing != null) {
                int a = containing.a, b = containing.b, c = containing.c;
                Remove(a, b, c);
                check.Add(new Edge(a, b));
                check.Add(new Edge(b, c));
                check.Add(new Edge(c, a));
            } else {
                foreach (Edge e in HullEdges())
                    if (Predicates.Orient(points[e.a], points[e.b], points[site]) < 0)
                        check.Add(new Edge(e.b, e.a));
                visible = check.Count;
            }
            foreach (Edge e in check)
                Add(e.a, e.b, site);
            int flips = 0;
            while (check.Count != 0) {
                Edge edge = check.Min;
                check.Remove(edge);
                int a = edge.a, b = edge.b;
                int q = directed.GetValueOrDefault(new Edge(b, a));
                if (q != 0 && Predicates.Incircle(points[a], points[b], points[site], points[q]) > 0) {
                    Remove(a, b, site);
                    Remove(b, a, q);
                    Add(a, q, site);
                    Add(q, b, site);
                    check.Add(new Edge(a, q));
                    check.Add(new Edge(q, b));
                    flips++;
                }
            }
            return new Insertion(containing == null ? "outside" : "inside", containing, visible, flips,
                                 directed.Count / 3, HullEdges().Count);
        }
    }
    public record Walk(List<int> path, Edge outside) {
    }
    public static Walk VisibilityWalk(Predicates.Point query, List<Predicates.Point> points,
                                      List<Triangle> triangles, Dictionary<Edge, int> directed) {
        List<int> path = new();
        path.Add(1);
        while (true) {
            Triangle t = triangles[path[^1] - 1];
            bool moved = false;
            foreach (Edge e in new Edge[] { new Edge(t.a, t.b), new Edge(t.b, t.c), new Edge(t.c, t.a) })
                if (Predicates.Orient(points[e.a], points[e.b], query) < 0) {
                    int next = directed.GetValueOrDefault(new Edge(e.b, e.a));
                    if (next == 0)
                        return new Walk(path, Key(e.a, e.b));
                    path.Add(next);
                    moved = true;
                    break;
                }
            if (!moved)
                return new Walk(path, null);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class Voronoi {
    public record Vertex(Predicates.Center center, double r2, string position) {
    }
    public record RealPoint(double x, double y) {
    }
    public static double Radius2(Predicates.Point a, Predicates.Point b, Predicates.Point c) {
        long area = Predicates.Orient(a, b, c);
        return (((double)Predicates.D2(a, b) * Predicates.D2(b, c)) * Predicates.D2(c, a)) /
               ((4.0 * area) * area);
    }
    public static string Position(Predicates.Center v, List<int> hull, List<Predicates.Point> points) {
        bool on = false;
        for (int i = 0; i < hull.Count; i++) {
            Predicates.Point a = points[hull[i]], b = points[hull[(i + 1) % hull.Count]];
            long sigma = (b.x - a.x) * (v.y - a.y * v.d) - (b.y - a.y) * (v.x - a.x * v.d);
            if (sigma < 0)
                return "outside";
            if (sigma == 0)
                on = true;
        }
        return on ? "on" : "inside";
    }
    public static Predicates.Point Outward(Predicates.Point a, Predicates.Point b) {
        return Predicates.Reduce(b.y - a.y, a.x - b.x);
    }
    public static List<int> Neighbors(int site, List<int> adjacent,
                                      Dictionary<Triangulation.Edge, int> directed, int next) {
        int start = next == 0 ? adjacent.Min() : next;
        List<int> result = new();
        int current = start;
        while (true) {
            result.Add(current);
            int following = directed.GetValueOrDefault(new Triangulation.Edge(site, current));
            if (following == 0 || following == start)
                break;
            current = following;
        }
        return result;
    }
    public static double Area(int site, List<int> vertexIds, List<Vertex> vertices,
                              List<Predicates.Point> points) {
        Predicates.Point origin = points[site];
        double sum = 0;
        for (int i = 0; i < vertexIds.Count; i++) {
            Predicates.Center a = vertices[vertexIds[i] - 1].center,
                              b = vertices[vertexIds[(i + 1) % vertexIds.Count] - 1].center;
            double u = (double)a.x / a.d - origin.x, w = (double)a.y / a.d - origin.y,
                   un = (double)b.x / b.d - origin.x, wn = (double)b.y / b.d - origin.y;
            sum += u * wn - un * w;
        }
        return sum / 2;
    }
    public static double Clipped(int site, List<int> neighbors, List<Predicates.Point> points) {
        List<RealPoint> polygon = new(
            [new RealPoint(0, 0), new RealPoint(1000, 0), new RealPoint(1000, 1000), new RealPoint(0, 1000)]);
        Predicates.Point s = points[site];
        foreach (int neighbor in neighbors) {
            Predicates.Point t = points[neighbor];
            long c1 = 2 * (t.x - s.x), c2 = 2 * (t.y - s.y),
                 c3 = t.x * t.x + t.y * t.y - s.x * s.x - s.y * s.y;
            List<RealPoint> next = new();
            for (int i = 0; i < polygon.Count; i++) {
                RealPoint a = polygon[i], b = polygon[(i + 1) % polygon.Count];
                double fa = c1 * a.x + c2 * a.y - c3, fb = c1 * b.x + c2 * b.y - c3;
                if (fa <= 0)
                    next.Add(a);
                if (fa < 0 && fb > 0 || fb < 0 && fa > 0) {
                    double lambda = fa / (fa - fb);
                    next.Add(new RealPoint(a.x + (b.x - a.x) * lambda, a.y + (b.y - a.y) * lambda));
                }
            }
            polygon = next;
        }
        double sum = 0;
        for (int i = 0; i < polygon.Count; i++) {
            RealPoint a = polygon[i], b = polygon[(i + 1) % polygon.Count];
            sum += a.x * b.y - b.x * a.y;
        }
        return sum / 2;
    }
}
